function dRace(array $f,array $payload,int $workers): array{$children=[];for($n=0;$n<$workers;++$n){$pipes=[];$proc=proc_open([PHP_BINARY,__DIR__.'/support-d-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,bEnvironment($f));if(!is_resource($proc)){throw new RuntimeException('Worker unavailable');}fwrite($pipes[0],json_encode($payload,JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$proc,$pipes];}$results=[];foreach($children as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($proc));same('',$err);$results[]=json_decode($out,true,16,JSON_THROW_ON_ERROR);}return $results;}
